===clients/queries.ts===
import { getJson, postJson } from '../../api/http';

// Server data under ONE shared key: anything showing clients reads ['clients'], and a write
// invalidates the same key to refresh them all (CLAUDE.md rule 5).
export type Client = { id: number; name: string; email: string };

export const clientsKey = ['clients'] as const;

// The URL search-param key the search box owns and the list reads (CLAUDE.md rule 4). Shared as a
// constant so the two files agree on the one key without importing each other's components.
export const CLIENT_SEARCH_PARAM = 'clientSearch';

// Case-insensitive match of a client's name against the current search text. An empty box matches
// every client, so the unfiltered list shows.
export function matchesClientSearch(client: Client, query: string): boolean {
  return client.name.toLowerCase().includes(query.trim().toLowerCase());
}

// A "proper email address": one @, non-empty local and domain parts, and a dotted domain. Shared by
// the form and mirrored by the server so a malformed address can never be saved.
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function isValidEmail(email: string): boolean {
  return EMAIL_PATTERN.test(email.trim());
}

export function fetchClients(): Promise<Client[]> {
  return getJson<Client[]>('/api/clients');
}

// A client's own projects, under a key nested beneath ['clients'] so invalidating clients refreshes
// them too (CLAUDE.md rule 5). The row carries the project's lifecycle `status` and `archived` flag
// too, so the client's page can show just the active ones by default and reveal the rest on its
// toggle without a second request. The server-side join also supplies a client name we don't render.
export type ClientProject = {
  id: number;
  name: string;
  status: string;
  archived: boolean;
};

export const clientProjectsKey = (clientId: number) =>
  ['clients', clientId, 'projects'] as const;

export function fetchClientProjects(clientId: number): Promise<ClientProject[]> {
  return getJson<ClientProject[]>(`/api/clients/${clientId}/projects`);
}

// The URL search-param key the "show all projects" toggle owns and the projects table reads
// (CLAUDE.md rule 4). Off by default → only ACTIVE, non-archived projects show; on → the finished
// and hidden (archived) ones show too. Shared as a constant so the two files agree on the one key
// without importing each other's components.
export const CLIENT_PROJECTS_SHOW_ALL_PARAM = 'clientProjectsAll';

// An "active" project — one the user is currently working on: ACTIVE lifecycle status and not
// archived (a tucked-away project is hidden even if still ACTIVE). The client's page shows these by
// default; the toggle reveals the finished and hidden ones.
export function isActiveProject(project: ClientProject): boolean {
  return project.status === 'ACTIVE' && !project.archived;
}

// A client's statement: every invoice raised for the client (across their projects) plus the total
// still owed, under a key nested beneath ['clients'] so invalidating clients refreshes it too
// (CLAUDE.md rule 5). Each invoice carries the money still due (amount - payments), derived
// server-side; the total is the sum of those dues.
export type StatementInvoice = { id: number; amount: number; status: string; due: number };
export type ClientStatement = { invoices: StatementInvoice[]; totalOwed: number };

export const clientStatementKey = (clientId: number) =>
  ['clients', clientId, 'statement'] as const;

export function fetchClientStatement(clientId: number): Promise<ClientStatement> {
  return getJson<ClientStatement>(`/api/clients/${clientId}/statement`);
}

// The URL search-param key the "open statement" control owns and the panel reads (CLAUDE.md rule 4).
export const CLIENT_STATEMENT_PARAM = 'clientStatement';

export function createClient(input: { name: string; email: string }): Promise<Client> {
  return postJson<Client>('/api/clients', input);
}

/** Archive (tuck away) a client so it drops off the list and search but is retained; id is in the
 * path, no body needed. */
export function archiveClient(clientId: number): Promise<void> {
  return postJson<void>(`/api/clients/${clientId}/archive`, {});
}
===projects/queries.ts===
import { getJson, postJson } from '../../api/http';

// Server data under ONE shared key: anything showing projects reads ['projects'], and a write
// invalidates the same key to refresh them all (CLAUDE.md rule 5). A project's row carries its
// client's NAME (the cross-entity join is done server-side, in ProjectView).
export type ProjectView = {
  id: number;
  name: string;
  clientName: string;
  archived: boolean;
  status: ProjectStatus;
  tagIds: number[];
};

// A project's lifecycle status: ACTIVE while worked on, ON_HOLD when paused, FINISHED when done.
// The one list the form's picker offers and the row displays, so both agree without importing.
export type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';

export const PROJECT_STATUSES: ProjectStatus[] = ['ACTIVE', 'ON_HOLD', 'FINISHED'];

export const projectsKey = ['projects'] as const;

// The URL search-param key the show-archived toggle owns and the list reads (CLAUDE.md rule 4).
// Shared as a constant so the two files agree on the one key without importing each other.
export const PROJECTS_SHOW_ARCHIVED_PARAM = 'showArchived';

// The URL search-param key the label filter owns and the list reads (CLAUDE.md rule 4): the chosen
// tag id, or absent for "all". Shared as a constant so the two files agree on the one key.
export const PROJECTS_TAG_FILTER_PARAM = 'tag';

// The URL search-param key the status filter owns and the list reads (CLAUDE.md rule 4): the chosen
// lifecycle status (ACTIVE / ON_HOLD / FINISHED), or absent for "all". Shared as a constant so the
// two files agree on the one key without importing each other.
export const PROJECTS_STATUS_FILTER_PARAM = 'status';

// The shared pool of labels, read under the SHARED ['tags'] key (CLAUDE.md rule 5) — the projects
// filter and the project-detail label picker stay in step through the key, without importing each
// other: attaching a label elsewhere invalidates ['tags'] and this select updates itself.
export type TagOption = { id: number; name: string };

export const tagsKey = ['tags'] as const;

export function fetchTagOptions(): Promise<TagOption[]> {
  return getJson<TagOption[]>('/api/tags');
}

export function fetchProjects(): Promise<ProjectView[]> {
  return getJson<ProjectView[]>('/api/projects');
}

export function createProject(
  input: { name: string; clientId: number; status: ProjectStatus },
): Promise<ProjectView> {
  return postJson<ProjectView>('/api/projects', input);
}

/** Delete a project the user no longer needs; the id is in the path, no body needed. */
export function deleteProject(projectId: number): Promise<void> {
  return postJson<void>(`/api/projects/${projectId}/delete`, {});
}

/** Archive (tuck away) a project so it drops off the lists but is retained; id is in the path. */
export function archiveProject(projectId: number): Promise<void> {
  return postJson<void>(`/api/projects/${projectId}/archive`, {});
}

// The client options the form's select needs. Read under the SHARED ['clients'] key (CLAUDE.md
// rule 5) — features never import each other, they stay in step through the key: creating a client
// elsewhere invalidates ['clients'] and this select updates itself.
export type ClientOption = { id: number; name: string };

export const clientsKey = ['clients'] as const;

export function fetchClientOptions(): Promise<ClientOption[]> {
  return getJson<ClientOption[]>('/api/clients');
}
===ClientsTable===
import { useQuery } from '@tanstack/react-query';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { ClientRow } from '../../slots/defs/clientRow';
import {
  CLIENT_SEARCH_PARAM,
  clientsKey,
  fetchClients,
  matchesClientSearch,
} from './queries';

// The list. Queries for itself under ['clients'] — never handed its data by a parent (CLAUDE.md
// rule 5). The search box owns the filter text in the URL; the list reads the same key (rule 4) and
// filters the already-loaded rows. Empty state and table carry the stable data-testid contract.
export function ClientsTable() {
  const { data: clients } = useQuery({ queryKey: clientsKey, queryFn: fetchClients });
  const [query] = useSearchParam(CLIENT_SEARCH_PARAM, asString);

  if (!clients) {
    return null;
  }

  if (clients.length === 0) {
    return <p data-testid="clients-empty">No clients yet.</p>;
  }

  const visible = clients.filter((client) => matchesClientSearch(client, query));

  return (
    <table data-testid="clients-table">
      <thead>
        <tr>
          <th>Name</th>
          <th>Email</th>
          <th />
        </tr>
      </thead>
      <tbody>
        {visible.map((client) => (
          <tr key={client.id} data-testid={`client-row-${client.id}`}>
            <td data-testid="client-name">{client.name}</td>
            <td data-testid="client-email">{client.email}</td>
            <td>
              <ClientRow.Slot clientId={client.id} />
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

